def _row(t, k):
    m, f, l, d, c, item, price, sal, go = _T[t]
    mpf = min(sal, 30000) * 5 // 100
    profit = 100000
    tax = profit * 825 // 10000
    r = [
     ("Read the market: " + m + ".", "Count 20 buyers in one district and note who they now use."),
     ("Fit locally: " + f + ".", "Score fit 1 to 5 for demand, rent and rivals, and note why."),
     ("Register and license: " + l + ". Register the firm with the companies registry and get a business registration certificate.", "Sole trader or limited company: pick one and note the costs and risks of each."),
     ("Data and trust: " + d + ". Follow the personal data law: say why you collect, keep it short, allow access and correction.", "Write a 5-line privacy notice in plain English and Chinese."),
     ("Find customers: " + c + ".", "Make a list of 30 target names and send 10 messages this week."),
     ("Price and tax in HKD: sell each " + item + " at HKD {:,}. There is no sales tax or VAT; profits tax applies (check current rule).".format(price), "If profit is HKD 100,000 and the first tier rate is 8.25%, tax is HKD {:,}.".format(tax)),
     ("People and partners: staff and the owner pay into the pension fund (MPF); each side pays 5% of pay, capped at monthly HKD 1,500 (check current rule). Sign written work terms.", "A HKD {:,} monthly salary: you pay HKD {:,} MPF, staff pay HKD {:,}; your cost is HKD {:,}.".format(sal, mpf, mpf, sal+mpf)),
     ("Launch plan: run a 4-week pilot, track money weekly. " + go + ".", "Set a go/no-go date, 4 weeks from launch, and write the one number that decides it."),
    ]
    return r

R_hk_1 = {t: _row(t, 0) for t in _T}
